const CACHE_NAME = 'porto-v1';
const ASSETS_CACHE = 'assets-cache-v1';
const API_CACHE = 'api-cache-v1';

// Get the list of files generated by Vite during build
// These would typically be located in the dist folder after build
const urlsToCache = [
  '/',
  '/index.html',
  '/offline.html',
  '/site.webmanifest',
  '/favicon.svg',
  '/favicon.ico',
  '/favicon-16x16.png',
  '/favicon-32x32.png',
  '/android-chrome-192x192.png',
  '/android-chrome-512x512.png',
  '/apple-touch-icon.png',
  '/portrait.png'
];

// Install event - cache basic assets
self.addEventListener('install', (event) => {
  console.log('[Service Worker] Installing...');
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then((cache) => {
        console.log('[Service Worker] Caching basic assets');
        return cache.addAll(urlsToCache);
      })
      .then(() => self.skipWaiting())
  );
});

// Activate event - clean up old caches
self.addEventListener('activate', (event) => {
  console.log('[Service Worker] Activating...');
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cacheName) => {
          if (cacheName !== CACHE_NAME && cacheName !== ASSETS_CACHE && cacheName !== API_CACHE) {
            console.log('[Service Worker] Deleting old cache:', cacheName);
            return caches.delete(cacheName);
          }
        })
      );
    }).then(() => self.clients.claim())
  );
});

// Fetch event - serve from cache, fallback to network
self.addEventListener('fetch', (event) => {
  // Don't cache cross-origin requests
  if (event.request.url.startsWith(self.location.origin)) {
    // Handle different types of requests differently
    if (event.request.destination === 'script' || event.request.destination === 'style') {
      // Cache JS/CSS files separately
      event.respondWith(
        caches.match(event.request).then((response) => {
          return response || fetchAndCache(event.request, ASSETS_CACHE);
        })
      );
    } else if (event.request.destination === 'image') {
      // Cache images separately
      event.respondWith(
        caches.match(event.request).then((response) => {
          return response || fetchAndCache(event.request, ASSETS_CACHE);
        })
      );
    } else {
      // Handle document requests (HTML) and API calls
      event.respondWith(
        caches.match(event.request).then((response) => {
          return response || fetch(event.request)
            .then(response => {
              // Don't cache error responses
              if (!response || response.status !== 200 || response.type !== 'basic') {
                return response;
              }
              
              // Clone the response to store in cache
              const responseToCache = response.clone();
              
              // Cache the response
              caches.open(CACHE_NAME).then((cache) => {
                cache.put(event.request, responseToCache);
              });
              
              return response;
            }).catch(() => {
              // Fallback to offline page if available
              if (event.request.headers.get('accept').includes('text/html')) {
                return caches.match('/offline.html') || caches.match('/');
              }
            });
        })
      );
    }
  } else {
    // For cross-origin requests, just fetch from network
    event.respondWith(fetch(event.request));
  }
});

// Helper function to fetch and cache a request
function fetchAndCache(request, cacheName) {
  return fetch(request)
    .then(response => {
      if (!response || response.status !== 200 || response.type !== 'basic') {
        return response;
      }
      
      // Clone the response to store in cache
      const responseToCache = response.clone();
      
      caches.open(cacheName).then((cache) => {
        cache.put(request, responseToCache);
      });
      
      return response;
    })
    .catch(error => {
      console.error('Failed to fetch and cache:', request.url, error);
      // Try to return cached version if fetch fails
      return caches.match(request);
    });
}